### C++

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <deque>
using namespace std;
using ll = long long;

const ll INF = 1e18;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k;
    cin >> n >> m >> k;

    // 读入全能补给站
    vector<bool> supply(n, false);
    vector<int> supplyNodes;
    supplyNodes.reserve(k);
    for (int i = 0; i < k; ++i) {
        int r;
        cin >> r;
        --r;  // 转为 0-based
        supply[r] = true;
        supplyNodes.push_back(r);
    }

    // 建图：正向带权图 + 反向无权图
    vector<vector<pair<int, int>>> g(n);   // 正图: (v, w)
    vector<vector<int>> rg(n);              // 反图: 可到达该结点的结点列表

    for (int i = 0; i < m; ++i) {
        int u, v, w;
        cin >> u >> v >> w;
        --u; --v;
        g[u].push_back({v, w});
        rg[v].push_back(u);
    }

    // 第一步：Dijkstra 求从起点到所有星球的最小费用
    vector<ll> dist(n, INF);
    dist[0] = 0;   // 起点为星球1，0-index 为 0
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<>> pq;
    pq.push({0, 0});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();
        if (d != dist[u]) continue;
        for (auto [v, w] : g[u]) {
            ll nd = d + w;
            if (nd < dist[v]) {
                dist[v] = nd;
                pq.push({nd, v});
            }
        }
    }

    // 第二步：反向 BFS 标记能到达终点的结点
    vector<bool> canReach(n, false);
    canReach[n - 1] = true;  // 终点自身可达
    deque<int> q;
    q.push_back(n - 1);

    while (!q.empty()) {
        int u = q.front();
        q.pop_front();
        for (int v : rg[u]) {  // 沿反向边走
            if (!canReach[v]) {
                canReach[v] = true;
                q.push_back(v);
            }
        }
    }

    // 第三步：枚举所有补给站，取最小 dist[p]
    ll ans = INF;
    for (int p : supplyNodes) {
        if (canReach[p] && dist[p] < ans) {
            ans = dist[p];
        }
    }

    cout << (ans >= INF ? -1 : ans) << '\n';
    return 0;
}
